package com.nyayaconnect.web;
import com.nyayaconnect.audit.AuditService;import com.nyayaconnect.auth.SpringAccess;import com.nyayaconnect.common.*;import com.nyayaconnect.security.AuthenticationFilter;import com.nyayaconnect.security.SessionUser;import com.nyayaconnect.user.UserRole;import jakarta.servlet.http.*;import org.springframework.jdbc.core.JdbcTemplate;import java.io.IOException;import java.util.*;
public final class AdminActionServlet extends HttpServlet {private JdbcTemplate db;private AuditService audit;public void init(){db=SpringAccess.bean(getServletContext(),JdbcTemplate.class);audit=SpringAccess.bean(getServletContext(),AuditService.class);}
 protected void doPost(HttpServletRequest req,HttpServletResponse res)throws IOException{try{SessionUser u=(SessionUser)req.getSession(false).getAttribute(AuthenticationFilter.SESSION_KEY);if(u==null||u.role()!=UserRole.ADMIN)throw new SecurityException("Administrator access is required.");String[] p=req.getPathInfo().split("/");if(p.length<3)throw new IllegalArgumentException("Admin action is required.");UUID id=UUID.fromString(p[1]);String action=p[2];if("block".equals(action)){int n=db.update("update users set blocked=not blocked where id=?",id.toString());if(n!=1)throw new IllegalArgumentException("User not found.");audit.record(u,"USER_BLOCK_TOGGLE","user",id.toString(),"SUCCESS",req.getRemoteAddr(),String.valueOf(req.getAttribute("X-Correlation-Id")));Api.json(res,200,Map.of("status","UPDATED","userId",id));return;}if("lawyer-status".equals(action)){Map<?,?> b=Json.MAPPER.readValue(req.getInputStream(),Map.class);String status=String.valueOf(b.get("status"));Set<String> allowed=Set.of("PENDING","UNDER_REVIEW","VERIFIED","REJECTED","EXPIRED","SUSPENDED");if(!allowed.contains(status))throw new IllegalArgumentException("Invalid verification status.");int n=db.update("update lawyer_profiles set verification_status=? where id=?",status,id.toString());if(n!=1)throw new IllegalArgumentException("Lawyer profile not found.");audit.record(u,"LAWYER_VERIFICATION_STATUS","lawyer_profile",id.toString(),"SUCCESS",req.getRemoteAddr(),String.valueOf(req.getAttribute("X-Correlation-Id")));Api.json(res,200,Map.of("status","UPDATED","lawyerId",id));return;}throw new IllegalArgumentException("Unknown admin action.");}catch(SecurityException e){Api.error(res,403,"FORBIDDEN",e.getMessage());}catch(IllegalArgumentException e){Api.error(res,400,"INVALID_REQUEST",e.getMessage());}catch(Exception e){Api.error(res,500,"ADMIN_ACTION_FAILED","Administrative update failed.");}}
}
